end = html.index(';const QUESTIONS=', start)
html = html[:start] + 'const DB=' + json.dumps(bank,ensure_ascii=False,separators=(',',':')) + html[end:]

def between(a,b,new):
    global html
    i=html.index(a)
    j=html.index(b,i)
    html=html[:i]+new+'\n'+html[j:]

html=html.replace('<title>하준이 수학 탐험 | 초4 실력 진단 & 사고력</title>','<title>하준이 수학 탐험 | 첫 진단부터 경시 준비까지</title>')
