html=html.replace('하준이 수학 탐험 1.0 · 2022 개정 교육과정 참고 · 자체 제작 문제 · 진단 결과는 참고용이며 표준화 평가가 아닙니다.','하준이 수학 탐험 2.0 · 자체 제작·검토 문항 · 첫 진단은 학습 방향을 정하는 참고 자료입니다.')
html=html.replace("function setPage(p){page=p;state.active=null;save();render()}","function setPage(p){page=p;save();render()}")
html=html.replace("function latestDiag(){return [...state.sessions].reverse().find(s=>s.mode==='diagnostic')}","function latestDiag(){return [...state.sessions].reverse().find(s=>s.mode==='diagnostic'&&s.responses.some(r=>byId[r.qid]?.term==='5-1'))}")
html=html.replace("else if(page==='quiz')main.innerHTML=quiz();","else if(page==='lesson')main.innerHTML=lessonPage();else if(page==='quiz')main.innerHTML=quiz();")
html=html.replace("['home','report','units','parent'].includes(page)?page:'home'","page==='lesson'?'units':(['home','report','units','parent'].includes(page)?page:'home')")
html=html.replace("inputmode=\"decimal\" placeholder=\"답을 입력하세요\"","inputmode=\"${q.answer.includes('/')?'text':'decimal'}\" placeholder=\"답을 입력하세요\"")
html=html.replace("function equal(a,b){if(normalize(a)===normalize(b))return true;let aa=Number(normalize(a)),bb=Number(normalize(b));return normalize(a)!==''&&normalize(b)!==''&&Number.isFinite(aa)&&Number.isFinite(bb)&&Math.abs(aa-bb)<1e-9}","function rational(x){let s=normalize(x),m=s.match(/^([0-9]+)과([0-9]+)\\/([1-9][0-9]*)$/);if(m)return Number(m[1])+Number(m[2])/Number(m[3]);m=s.match(/^([0-9]+)\\/([1-9][0-9]*)$/);if(m)return Number(m[1])/Number(m[2]);return s!==''&&Number.isFinite(Number(s))?Number(s):NaN}function equal(a,b,q){if(normalize(a)===normalize(b))return true;if(q?.strict_format)return false;let aa=rational(a),bb=rational(b);return Number.isFinite(aa)&&Number.isFinite(bb)&&Math.abs(aa-bb)<1e-9}")
html=html.replace('equal(selected,q.answer)','equal(selected,q.answer,q)')
html=html.replace('${esc(q.stem)}</h2>${choices}','${esc(q.stem)}</h2>${visual(q)}${choices}')
html=html.replace('4학년 수학 진단 완료','첫 수학 진단 완료')
