html=html.replace('① 처음에는 도움 없이 24문항 진단<br>② 틀린 문제의 이유를 아이가 직접 선택<br>③ 취약 단원과 연산 9단계를 병행<br>④ 일주일에 경시형 문제 1~2개 도전<br>⑤ 2~4주 후 재평가','① 도움 없이 20문항 첫 진단<br>② 틀린 개념을 말로 설명하고 예제 풀기<br>③ 기존 연산 문제집은 하루 10분 안팎으로 병행<br>④ 초5-1은 개념→기본→적용 순서로 진행<br>⑤ 사고력은 주 1~2회 풀이 이유까지 설명<br>⑥ 2~4주 뒤 다시 진단')
html=html.replace('첫 진단은 작은 표본이므로 한 단원에서 1개 틀렸다는 이유만으로 결손을 단정하지 마세요.','첫 진단은 한 영역당 약 1문항인 작은 표본입니다. 단원별 추가 학습과 아이의 풀이 설명을 함께 보세요.')

between('function home(){','function start(',r'''function home(){let l=latestDiag(),att=state.sessions.flatMap(s=>s.responses),got=att.filter(r=>r.correct).length;
if(!l)return `<section class="hero"><div class="eyebrow">START HERE · 첫 수학 진단</div><h1>하준아, 먼저 지금 실력을<br>함께 알아보자!</h1><p>초4 기초 12문항, 초5-1 선행 6문항, 사고력 2문항을 풀어요. 약 25~35분. 계산은 연습장에 하고, 모르면 추측했다고 표시해도 괜찮아.</p><button class="primary" onclick="start('diagnostic')">첫 진단 시작하기 →</button></section><div class="panel" style="margin-top:18px"><h3>진단을 마친 다음</h3><p class="help">틀린 개념부터 짧게 설명하고 기본·적용 문제를 풀어요. 이미 쓰는 연산 문제집은 그대로 병행하고, 5-1은 준비된 단원부터 선행해요. 사고력은 풀이 이유를 말하는 연습부터 시작합니다.</p></div>${state.active?`<div class="panel" style="margin-top:18px"><button class="secondary" onclick="resumeQuiz()">진행 중인 진단 이어하기</button></div>`:''}`;
let g4=l.responses.filter(r=>byId[r.qid]?.grade===4&&byId[r.qid]?.role!=='challenge'),g5=l.responses.filter(r=>byId[r.qid]?.term==='5-1'),think=l.responses.filter(r=>byId[r.qid]?.role==='challenge');let p=xs=>xs.length?Math.round(xs.filter(r=>r.correct).length/xs.length*100):0;
return `<section class="hero"><div class="eyebrow">MATH EXPLORER · STEP BY STEP</div><h1>오늘은 한 개념씩<br>더 깊게 생각해 보자!</h1><p>첫 진단을 마쳤어요. 4학년 빈틈을 확인하고, 5학년 1학기 선행과 사고력으로 이어가요.</p><button class="primary" onclick="setPage('report')">나의 학습 경로 보기 →</button></section><div class="statgrid"><div class="stat"><strong>${p(g4)}%</strong><span>초4 첫 진단</span></div><div class="stat"><strong>${p(g5)}%</strong><span>초5-1 첫 진단</span></div><div class="stat"><strong>${p(think)}%</strong><span>사고력 첫 진단</span></div><div class="stat"><strong>${att.length}</strong><span>푼 문제 기록</span></div></div><div class="section-head"><h2>다음 학습</h2></div><div class="grid3"><article class="mode-card"><div class="emoji">📘</div><h3>개념부터</h3><p>초4·초5-1 단원에서 짧은 설명과 예제를 보고 문제를 풀어요.</p><button class="secondary" onclick="setPage('units')">단원 선택</button></article><article class="mode-card"><div class="emoji">🔄</div><h3>오답 복습</h3><p>틀렸거나 추측한 문제를 다시 풀고 이유를 기록해요.</p><button class="secondary" onclick="start('review')">다시 풀기</button></article><article class="mode-card"><div class="emoji">🏆</div><h3>사고력 도전</h3><p>규칙·논리·경우의 수를 먼저 설명하고 풀어요.</p><button class="secondary" onclick="start('challenge')">5문제 도전</button></article></div>${state.active?`<div class="panel" style="margin-top:18px"><button class="secondary" onclick="resumeQuiz()">진행 중인 문제 이어하기</button></div>`:''}<p class="notice" style="margin-top:18px">새 단원은 이전 단원 개념을 설명하고 적용 문제까지 풀 수 있을 때 진행하세요. 점수 하나만으로 선행 여부를 결정하지 않아요.</p>`}
function resumeQuiz(){if(state.active){page='quiz';resetQ();render()}}
''')

between('function start(','function resetQ(',r'''function start(mode,unitId,tier){if(state.active?.responses?.length&&!confirm('진행 중인 문제를 멈추고 새 학습을 시작할까요?'))return;let qs;if(mode==='diagnostic'){let round=state.sessions.filter(s=>s.mode==='diagnostic'&&s.responses.some(r=>byId[r.qid]?.term==='5-1')).length%2;let g4=DB.units.filter(u=>u.term.startsWith('4-')).map(u=>DIAG.filter(q=>q.unit_id===u.unit_id)[round]||DIAG.find(q=>q.unit_id===u.unit_id));let g5=DB.units.filter(u=>u.term==='5-1').map(u=>QUESTIONS.find(q=>q.unit_id===u.unit_id&&(round?q.id.endsWith('-02'):q.role==='placement')));let reasoning=round?['C4-08','C5-02']:['C4-04','C4-01'];qs=[...g4,...g5,...reasoning.map(id=>byId[id])].map(q=>q.id)}else if(mode==='challenge'){let seen=new Set(state.sessions.filter(s=>s.mode==='challenge').flatMap(s=>s.responses.filter(r=>r.correct).map(r=>r.qid)));let pool=CHALLENGE.filter(q=>tier===1?q.level<=6:tier===2?q.level===7:tier===3?q.level>=8:true);qs=randomize(pool).sort((a,b)=>Number(seen.has(a.id))-Number(seen.has(b.id))||a.level-b.level).slice(0,5).map(q=>q.id)}else if(mode==='review'){let recent=state.sessions.flatMap(s=>s.responses).filter(r=>!r.correct||r.confidence!=='sure');qs=randomize([...new Set(recent.map(r=>r.qid))]).slice(0,10);if(!qs.length){alert('복습할 문제가 아직 없어요. 개념 학습에서 시작해요.');return setPage('units')}}else{let pool=unitId?QUESTIONS.filter(q=>q.unit_id===unitId&&q.role!=='challenge'&&q.role!=='archive'):PRACTICE;if(tier===1)pool=pool.filter(q=>q.level<=2);if(tier===2)pool=pool.filter(q=>q.level>=2);let performed=state.sessions.flatMap(s=>s.responses),wrong=new Set(performed.filter(r=>!r.correct).map(r=>r.qid)),seen=new Set(performed.map(r=>r.qid));qs=randomize(pool).sort((a,b)=>(wrong.has(a.id)?0:seen.has(a.id)?2:1)-(wrong.has(b.id)?0:seen.has(b.id)?2:1)).slice(0,10).map(q=>q.id);if(!qs.length)return alert('이 단계의 문제가 아직 없어요. 다른 단계를 선택해 주세요.')}state.active={id:'s'+Date.now(),mode,questions:qs,index:0,responses:[],startedAt:new Date().toISOString(),unitId:unitId||null};save();page='quiz';resetQ();render();window.scrollTo({top:0,behavior:'smooth'})}
''')

between('function unitsPage(){','function parent(){',r'''let lessonUnit=null;
function openLesson(id){lessonUnit=id;page='lesson';render();window.scrollTo({top:0,behavior:'smooth'})}
function unitStatus(id){let rs=state.sessions.filter(s=>s.mode==='practice'&&s.unitId===id).flatMap(s=>s.responses).filter(r=>byId[r.qid]?.unit_id===id);let ok=rs.filter(r=>r.correct).length;return new Set(rs.map(r=>r.qid)).size>=3&&new Set(state.sessions.filter(s=>s.mode==='practice'&&s.unitId===id).map(s=>s.id)).size>=2&&ok/rs.length>=.8?'적용 문제까지 확인':rs.length?'학습 중':'시작 전'}
function unitsPage(){let g4=DB.units.filter(u=>u.term.startsWith('4-')),g5=DB.units.filter(u=>u.term==='5-1');let cards=us=>`<div class="unitgrid">${us.map(u=>`<article class="unit"><small>${esc(u.term)} · ${esc(u.domain)}</small><h3 style="margin:8px 0">${esc(u.unit)}</h3><p class="micro">${unitStatus(u.unit_id)}</p><button class="soft" onclick="openLesson('${u.unit_id}')">개념부터 보기 →</button></article>`).join('')}</div>`;return `<div class="section-head"><h2>📚 단계별 수학 학습</h2></div><div class="panel"><h3>학습 순서</h3><p>① 첫 진단 → ② 약한 초4 개념 복습 → ③ 초5-1 한 단원씩 개념·기본·적용 → ④ 사고력 문제와 풀이 설명 → ⑤ 준비되면 초5-2 다음 단원</p><p class="help">연산 문제집은 짧게 꾸준히 사용하고, 웹에서는 개념을 말로 설명하고 문제를 해결하는 연습에 집중해요.</p></div><div class="section-head"><h2>초4 기초 확인</h2><small>빈틈을 채우는 단계</small></div>${cards(g4)}<div class="section-head"><h2>초5-1 선행</h2><small>한 번에 한 단원씩</small></div>${cards(g5)}<div class="panel" style="margin-top:20px"><h3>🏆 사고력·경시 준비</h3><p class="help">답을 빨리 맞히는 것보다 조건을 표시하고, 다른 풀이를 찾아보고, 왜 맞는지 설명하는 습관을 먼저 만들어요. 본 문제는 경시대회 기출문제가 아닌 자체 제작 연습문항입니다.</p><div class="inline-actions"><button class="secondary" onclick="start('challenge',null,1)">입문 3문제</button><button class="secondary" onclick="start('challenge',null,2)">발전 5문제</button><button class="secondary" onclick="start('challenge',null,3)">경시형 심화</button></div></div>`}
function lessonPage(){let u=DB.units.find(u=>u.unit_id===lessonUnit);if(!u)return unitsPage();return `<div class="section-head"><h2>${esc(u.term)} · ${esc(u.unit)}</h2></div><div class="panel"><span class="tag blue">1단계 · 개념</span><h3 style="margin-top:12px">핵심 개념</h3><p>${esc(u.concept)}</p><div class="insight"><b>예제</b><p>${esc(u.example)}</p></div><p class="help">확인: ${esc(u.check)}</p></div><div class="grid2" style="margin-top:18px"><div class="panel"><span class="tag">2단계 · 기본</span><h3 style="margin:12px 0">개념을 직접 써 보기</h3><p class="help">연습장에 방법을 적고 답을 입력해요. 힌트와 해설을 볼 수 있어요.</p><button class="secondary" onclick="start('practice','${u.unit_id}',1)">기본 문제 풀기</button></div><div class="panel"><span class="tag gold">3단계 · 적용</span><h3 style="margin:12px 0">조건을 읽고 해결하기</h3><p class="help">식이나 그림을 먼저 만들고 풀이 이유를 말해 보세요.</p><button class="secondary" onclick="start('practice','${u.unit_id}',2)">적용 문제 풀기</button></div></div><div class="panel" style="margin-top:18px"><h3>다음 단계로 넘어갈 때</h3><p class="help">문제 하나를 맞혔다고 끝내지 않아요. 다른 수로 다시 풀고, 왜 그런지 설명할 수 있는지 확인하세요. 5-1 단원은 이전 단원과 4학년 관련 개념에 큰 빈틈이 없을 때 진행해요.</p><button class="soft" onclick="setPage('units')">전체 단원 보기</button></div>`}
function visual(q){if(!q.visual)return '';let v=q.visual,labels=v.labels,vals=v.values,top=Math.max(...vals)+4;if(v.type==='bar')return `<div class="graph" role="img" aria-label="막대그래프: ${labels.map((x,i)=>x+' '+vals[i]+v.unit).join(', ')}"><div class="bars">${labels.map((x,i)=>`<div class="barcol"><span>${vals[i]}${esc(v.unit)}</span><div style="height:${Math.round(vals[i]/top*125)}px"></div><b>${esc(x)}</b></div>`).join('')}</div></div>`;return `<div class="graph" role="img" aria-label="꺾은선그래프: ${labels.map((x,i)=>x+' '+vals[i]+v.unit).join(', ')}"><svg viewBox="0 0 350 160" aria-hidden="true"><polyline fill="none" stroke="#2c9676" stroke-width="4" points="${vals.map((n,i)=>`${35+i*95},${140-Math.round(n/top*110)}`).join(' ')}"/>${vals.map((n,i)=>`<circle cx="${35+i*95}" cy="${140-Math.round(n/top*110)}" r="5" fill="#2c9676"/><text x="${35+i*95}" y="${125-Math.round(n/top*110)}" text-anchor="middle">${n}${esc(v.unit)}</text><text x="${35+i*95}" y="155" text-anchor="middle">${esc(labels[i])}</text>`).join('')}</svg></div>`}
''')

